fn agent_runtime_state_for_turn(state: &AgentTurnState) -> tau_proto::AgentRuntimeState {
    match state {
        AgentTurnState::Idle => tau_proto::AgentRuntimeState::Idle,
        AgentTurnState::AgentThinking { .. } | AgentTurnState::ToolsRunning { .. } => {
            tau_proto::AgentRuntimeState::Running
        }
    }
}

fn default_navigation_mode(
    originator: &tau_proto::PromptOriginator,
) -> tau_proto::AgentNavigationMode {
    if matches!(originator, tau_proto::PromptOriginator::Extension { .. }) {
        tau_proto::AgentNavigationMode::ActiveAuto
    } else {
        tau_proto::AgentNavigationMode::Active
    }
}

/// Classifies live activation without carrying or re-rendering message payload.
pub(crate) fn agent_message_activation_class(
    message: &tau_proto::AgentMessageReceived,
) -> Option<crate::agent::AgentMessageActivationClass> {
    use crate::agent::AgentMessageActivationClass::{
        IsolatedWatchNotification, OrdinaryAgentInput,
    };
    match message.kind {
        tau_proto::AgentMessageKind::Message
        | tau_proto::AgentMessageKind::WatchResponse
        | tau_proto::AgentMessageKind::WatchPrompt => Some(OrdinaryAgentInput),
        tau_proto::AgentMessageKind::WatchProviderStatus => message
            .watch_provider_status
            .as_ref()
            .is_some_and(|status| !status.initial)
            .then_some(IsolatedWatchNotification),
        tau_proto::AgentMessageKind::WatchWorkStatus => message
            .watch_work_status
            .as_ref()
            .is_some_and(|status| !status.initial)
            .then_some(IsolatedWatchNotification),
        tau_proto::AgentMessageKind::WatchLongWait => message
            .watch_long_wait
            .is_some()
            .then_some(IsolatedWatchNotification),
        tau_proto::AgentMessageKind::WatchLifecycle => message
            .watch_lifecycle
            .is_some()
            .then_some(IsolatedWatchNotification),
    }
}

fn watch_retirement_event_matches(
    event: &Event,
    completion: &interception::WatchRetirementCompletion,
) -> bool {
    matches!(
        event,
        Event::AgentMessageReceived(message)
            if message.message_id == completion.message_id
                && message.sender_id == completion.watched_agent_id
                && message.recipient_id == completion.watcher_id
                && message.kind == tau_proto::AgentMessageKind::WatchLifecycle
                && message.watch_lifecycle.is_some()
                && message.message.is_empty()
    )
}

fn provider_response_update_has_public_content(updated: &ProviderResponseUpdated) -> bool {
    // Provider-owned stats remain public content per
    // `SPEC-provider-response-streaming`.
    !updated.deltas.is_empty()
        || updated.compaction.is_some()
        || updated.status.is_some()
        || updated.response_stats.is_some()
}

